def column_totals(rows):
    if not rows:
        return []
    num_cols = len(rows[0])
    totals = []
    for i in range(num_cols):
        col_values = [row[i] for row in rows]
        if all(isinstance(val, (int, float)) for val in col_values):
            totals.append(sum(col_values))
        else:
            totals.append("")
    return totals

